import React from "react";

import template from "../../config/section-title--template";
import SectionTitleBase from "../../modules/section-title/SectionTitle";
import type { SectionTitleProps } from "../../modules/section-title/SectionTitle";

export type { SectionTitleAlign, SectionTitleVariant } from "../../modules/section-title/SectionTitle";

/** Everything the mechanism takes except the template, which is bound here. */
export type Props = Omit<SectionTitleProps, "template">;

/**
 * The section heading, configured.
 *
 * Import this — not the module — from any section:
 *
 *   <SectionTitle
 *     backgroundText="PROPERTIES"
 *     title="Featured Properties"
 *     description="Explore our latest available homes."
 *     align="left"
 *   />
 *
 * Restyle every heading on the site at once via config/section-title--template.
 */
export default function SectionTitle(props: Props) {
  return <SectionTitleBase template={template} {...props} />;
}
