import { useEffect, useRef, useState } from "react";

type Options = {
  /** Fraction of the element that must be visible. */
  threshold?: number;
  /** Shrinks the viewport so the reveal fires slightly inside the fold. */
  rootMargin?: string;
};

/**
 * Reports when an element first enters the viewport, then stops watching.
 *
 * One-shot by design: a section heading that re-animates every time it scrolls
 * back into view is distracting, and on a long page it fires constantly.
 *
 * Where IntersectionObserver is unavailable the hook reports visible
 * immediately, so content is never left hidden behind a missing API.
 */
export function useInView<T extends HTMLElement>({
  threshold = 0.15,
  rootMargin = "0px 0px -10% 0px",
}: Options = {}) {
  const ref = useRef<T>(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const element = ref.current;
    if (!element) return;

    if (typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }

    // Already on screen at mount — observers fire async, and for content above
    // the fold that delay is visible as a flash of hidden text.
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setInView(true);
          observer.disconnect();
        }
      },
      { threshold, rootMargin }
    );

    observer.observe(element);
    return () => observer.disconnect();
  }, [threshold, rootMargin]);

  return { ref, inView };
}

export default useInView;
