// Styling for the reusable property carousel: the section shell, the Swiper
// overrides and the custom controls.
//
// Deliberately separate from the property card. Search Results will drop the
// same card into a plain CSS grid with no Swiper at all, so nothing about the
// carousel may leak into the card's stylesheet.
//
// The Swiper override that matters most is `.swiper-slide { height: auto }`.
// Swiper sizes slides to the tallest by default only in some configurations;
// with height:auto plus align-items:stretch every slide fills the row, which is
// what lets the card's own margin-top:auto footer line up across all of them.

import brand from "../brand";

export type PropertyCarouselLabels = {
  previous: string;
  next: string;
  /** `{n}` is replaced by the slide number. */
  goToSlide: string;
  region: string;
};

export type PropertyCarouselTemplate = {
  css: string;
  rootClass: string;
  labels: PropertyCarouselLabels;
  /** The column the heading sits in, so the row can line its first card up. */
  layout: { maxWidth: number; gutter: number };
  breakpoints: {
    slidesPerView: number | "auto";
    spaceBetween: number;
    breakpoints: Record<
      number,
      { slidesPerView: number | "auto"; spaceBetween: number }
    >;
  };
};

const color = {
  background: brand.colors.background,
  backgroundAlt: brand.colors.backgroundAlt,

  arrowBorder: brand.colors.border,
  arrowIcon: brand.colors.primary,
  arrowHoverBorder: brand.colors.accent,
  arrowHoverIcon: brand.colors.accent,
  arrowDisabled: brand.colors.textMuted,

  bullet: brand.colors.border,
  bulletActive: brand.colors.accent,

  focus: brand.colors.accent,
};

const layout = {
  maxWidth: 1280,
  /** What a card measured at the old 3-per-view desktop breakpoint. */
  slideWidth: 380,
  arrowSize: 46,
  bulletWidth: 26,
  bulletWidthActive: 40,
  bulletHeight: 2,
  hideArrowsBelow: 640,
};

const spacing = {
  sectionTop: 104,
  /** Vertical breathing room so the hover lift is not clipped by the row. */
  slideBleed: 40,
  sectionBottom: 104,
  sectionTopCompact: 68,
  sectionBottomCompact: 68,
  gutter: 40,
  gutterCompact: 20,
  headGap: 40,
  paginationGap: 44,
  arrowGap: 10,
};

const ease = "cubic-bezier(.22, 1, .36, 1)";

const labels: PropertyCarouselLabels = {
  previous: "Previous properties",
  next: "Next properties",
  goToSlide: "Go to slide {n}",
  region: "Property carousel",
};

/**
 * Slide sizing is "auto": every width below comes from CSS instead of being
 * derived from the container. That is what lets the row span the window while
 * a card stays the size it always was - a count-based slidesPerView would have
 * divided the whole window by three and given 600px cards.
 */
const breakpoints = {
  slidesPerView: "auto" as const,
  spaceBetween: 16,
  breakpoints: {
    520: { slidesPerView: "auto" as const, spaceBetween: 20 },
    760: { slidesPerView: "auto" as const, spaceBetween: 24 },
    1080: { slidesPerView: "auto" as const, spaceBetween: 28 },
  },
};

const css = `
.kr-pcarousel {
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
  overflow: hidden;
}
.kr-pcarousel--alt { background: ${color.backgroundAlt}; }

.kr-pcarousel__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
}

/* Heading left, arrows right, bottom-aligned. */
.kr-pcarousel__head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
  margin-bottom: ${spacing.headGap}px;
}
.kr-pcarousel__head-title { flex: 1; min-width: 0; }

.kr-pcarousel__nav {
  display: flex;
  gap: ${spacing.arrowGap}px;
  flex-shrink: 0;
  padding-bottom: 6px;
}
.kr-pcarousel__arrow {
  width: ${layout.arrowSize}px;
  height: ${layout.arrowSize}px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid ${color.arrowBorder};
  border-radius: 50%;
  background: none;
  color: ${color.arrowIcon};
  cursor: pointer;
  transition: border-color .24s ${ease}, color .24s ${ease};
}
.kr-pcarousel__arrow:hover:not(:disabled) {
  border-color: ${color.arrowHoverBorder};
  color: ${color.arrowHoverIcon};
}
.kr-pcarousel__arrow:focus-visible {
  outline: 2px solid ${color.focus};
  outline-offset: 3px;
}
.kr-pcarousel__arrow:disabled {
  color: ${color.arrowDisabled};
  opacity: .4;
  cursor: default;
}

/* ── swiper ─────────────────────────────────────────────
   The row is pulled out of the centred column to the full width of the window.

   It used to sit inside the column and overflow it, which meant the right-hand
   margin was filled by the next card while the left-hand one stayed empty
   until the row had been advanced - on a fresh load the first card had a bare
   strip beside it. Spanning the window instead means there is no margin left
   over to look empty: cards run edge to edge, and the one leaving the frame on
   the right is the cue that the row continues.

   50% here is half the column's content box and 50vw is half the window, so
   the negative margin is exactly the gap between them on each side. */
.kr-pcarousel__swiper {
  overflow: hidden;
  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);
  /* Room for the hover lift and its 16px/40px shadow, which the clip would
     otherwise shear off. */
  padding: ${spacing.slideBleed}px 0;
}
/* Widths for slidesPerView: "auto". A card is the size it was at the old
   3-per-view desktop breakpoint; the window simply fits more of them. */
.kr-pcarousel__swiper .swiper-slide { width: ${layout.slideWidth}px; }
@media (max-width: 1079px) { .kr-pcarousel__swiper .swiper-slide { width: 46vw; } }
@media (max-width: 759px) { .kr-pcarousel__swiper .swiper-slide { width: 62vw; } }
@media (max-width: 519px) { .kr-pcarousel__swiper .swiper-slide { width: 82vw; } }
.kr-pcarousel__swiper .swiper-wrapper {
  align-items: stretch;
}
/* The line that makes every card the same height. */
.kr-pcarousel__swiper .swiper-slide {
  height: auto;
  display: flex;
}
.kr-pcarousel__swiper .swiper-slide > * { width: 100%; }

/* ── pagination ───────────────────────────────────────── */
.kr-pcarousel__pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-top: ${spacing.paginationGap}px;
}
.kr-pcarousel__pagination .swiper-pagination-bullet {
  width: ${layout.bulletWidth}px;
  height: ${layout.bulletHeight}px;
  border-radius: 0;
  background: ${color.bullet};
  opacity: 1;
  cursor: pointer;
  border: 0;
  padding: 0;
  transition: width .3s ${ease}, background-color .3s ${ease};
}
.kr-pcarousel__pagination .swiper-pagination-bullet-active {
  width: ${layout.bulletWidthActive}px;
  background: ${color.bulletActive};
}
.kr-pcarousel__pagination .swiper-pagination-bullet:focus-visible {
  outline: 2px solid ${color.focus};
  outline-offset: 4px;
}

/* ── responsive ───────────────────────────────────────── */
@media (max-width: 980px) {
  .kr-pcarousel {
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-pcarousel__inner { padding: 0 ${spacing.gutterCompact}px; }
  .kr-pcarousel__head { margin-bottom: 30px; }
}

@media (max-width: ${layout.hideArrowsBelow}px) {
  /* Touch users swipe; the arrows only crowd the header at this width. */
  .kr-pcarousel__nav { display: none; }
  .kr-pcarousel__pagination { margin-top: 30px; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-pcarousel__arrow,
  .kr-pcarousel__pagination .swiper-pagination-bullet {
    transition-duration: .01ms;
  }
}
`;

const template: PropertyCarouselTemplate = {
  css,
  rootClass: "kr-pcarousel",
  labels,
  breakpoints,
  layout: { maxWidth: layout.maxWidth, gutter: spacing.gutter },
};

export default template;
