import React, { useCallback, useEffect, useId, useRef, useState } from "react";
import { LuArrowLeft, LuArrowRight } from "react-icons/lu";
import { A11y, Autoplay, Keyboard, Navigation, Pagination } from "swiper/modules";
import { Swiper, SwiperSlide } from "swiper/react";
import type SwiperClass from "swiper";

import "swiper/css";

import type { PropertyCardTemplate } from "../../templates/property-card/default-template";
import type {
  PropertyCarouselLabels,
  PropertyCarouselTemplate,
} from "../../templates/property-carousel/default-template";
import usePrefersReducedMotion from "../shared/usePrefersReducedMotion";
import PropertyCard from "./PropertyCard";
import type { Property } from "./types";

export type PropertyCarouselProps = {
  /** Carousel shell, Swiper overrides and control styling. */
  template: PropertyCarouselTemplate;
  /** Card styling, forwarded to every slide. */
  cardTemplate: PropertyCardTemplate;
  properties: Property[];
  /** Section heading. Passed in so this reuses the shared SectionTitle. */
  heading?: React.ReactNode;
  hrefFor?: (slug: string) => string;
  /** Warm off-white section background instead of white. */
  alt?: boolean;
  /** Advance on its own. Always suspended under reduced motion. */
  autoplay?: boolean;
  /** Dwell per slide, in ms. */
  autoplayDelay?: number;
  enabled?: boolean;
  labels?: Partial<PropertyCarouselLabels>;
};

/**
 * Reusable property carousel.
 *
 * Built on Swiper rather than hand-rolled, per the brief.
 *
 * Autoplay is on by default and loops, so the row keeps moving instead of
 * stalling at the last card. It pauses the moment the pointer enters, since a
 * carousel that slides away while you are reading a rent figure is worse than
 * one that never moved; manual navigation does not switch it off permanently.
 * Under prefers-reduced-motion it never starts.
 *
 * Later reuse — Similar Properties on the property page — is just:
 *   <PropertyCarousel heading={...} properties={similar} />
 */
export default function PropertyCarousel({
  template,
  cardTemplate,
  properties,
  heading,
  hrefFor,
  alt = false,
  autoplay = true,
  autoplayDelay = 5000,
  enabled = true,
  labels: labelOverrides,
}: PropertyCarouselProps) {
  const labels = { ...template.labels, ...labelOverrides };

  // Unique per instance so two carousels on one page cannot capture each
  // other's controls. Colons in useId are not valid in CSS selectors.
  const uid = useId().replace(/:/g, "");
  const prevId = `${uid}-prev`;
  const nextId = `${uid}-next`;
  const pagerId = `${uid}-pager`;

  const swiperRef = useRef<SwiperClass | null>(null);
  const [atStart, setAtStart] = useState(true);
  const [atEnd, setAtEnd] = useState(false);
  const reducedMotion = usePrefersReducedMotion();

  /* Looping so autoplay has somewhere to go past the last card, rather than
     stalling at the end. */
  const looping = autoplay && properties.length > 3;

  /* Distance from the window edge to the page gutter. The row is full width
     while the heading above it is not, so this is what keeps the first card
     under the first letter of the title. Measured rather than assumed, because
     it depends on the window: it is zero once the window is narrower than the
     column, at which point the row and the heading share the same gutter. */
  const [edgeOffset, setEdgeOffset] = useState(0);
  useEffect(() => {
    const measure = () => {
      const column = Math.min(window.innerWidth, template.layout.maxWidth);
      setEdgeOffset((window.innerWidth - column) / 2 + template.layout.gutter);
    };
    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, [template.layout.maxWidth, template.layout.gutter]);

  /* Swiper reads offsets when it measures, so a resize has to re-measure. */
  useEffect(() => {
    swiperRef.current?.update();
  }, [edgeOffset]);

  useEffect(() => {
    const swiper = swiperRef.current;
    if (!swiper || !swiper.autoplay) return;
    // The preference can change after mount, so honour it live.
    if (reducedMotion) swiper.autoplay.stop();
    else if (autoplay) swiper.autoplay.start();
  }, [reducedMotion, autoplay]);

  /* On a fresh load the row rests on the first card, which leaves the strip
     between the window edge and the page gutter empty. Stepping forward once -
     instantly, with no animation - puts the previous card into that strip, so
     the row reads as continuous from the moment it appears rather than only
     after it has been advanced. Autoplay carries on at its normal pace from
     there. Only with loop on: without it, stepping forward would just skip the
     first property. */
  const stepped = useRef(false);

  const sync = useCallback((swiper: SwiperClass) => {
    swiperRef.current = swiper;
    // A looping carousel has no first or last slide, so the arrows stay live.
    setAtStart(!swiper.params.loop && swiper.isBeginning);
    setAtEnd(!swiper.params.loop && swiper.isEnd);
  }, []);

  if (!enabled || properties.length === 0) return null;

  const root = template.rootClass;

  return (
    <section
      className={`${root}${alt ? ` ${root}--alt` : ""}`}
      aria-roledescription="carousel"
      aria-label={labels.region}
    >
      <style>{template.css}</style>
      <style>{cardTemplate.css}</style>

      <div className={`${root}__inner`}>
        <div className={`${root}__head`}>
          <div className={`${root}__head-title`}>{heading}</div>

          <div className={`${root}__nav`}>
            <button
              type="button"
              id={prevId}
              className={`${root}__arrow ${root}__arrow--prev`}
              aria-label={labels.previous}
              disabled={atStart}
              onClick={() => swiperRef.current?.slidePrev()}
            >
              <LuArrowLeft size={17} strokeWidth={1.6} />
            </button>
            <button
              type="button"
              id={nextId}
              className={`${root}__arrow ${root}__arrow--next`}
              aria-label={labels.next}
              disabled={atEnd}
              onClick={() => swiperRef.current?.slideNext()}
            >
              <LuArrowRight size={17} strokeWidth={1.6} />
            </button>
          </div>
        </div>

        <Swiper
          className={`${root}__swiper`}
          modules={[Navigation, Pagination, Keyboard, A11y, Autoplay]}
          slidesPerView={template.breakpoints.slidesPerView}
          spaceBetween={template.breakpoints.spaceBetween}
          breakpoints={template.breakpoints.breakpoints}
          keyboard={{ enabled: true }}
          loop={looping}
          /* The row spans the window, so more cards are on screen than Swiper
             keeps rendered by default. Two spare either side means the card
             entering or leaving the frame is already drawn. */
          loopAdditionalSlides={looping ? 2 : 0}
          /* The row starts at the window edge, so a card sits under the page
             gutter rather than beginning at it. This pushes the first card back
             in line with the heading above it, and Swiper accounts for the
             offset when it measures, so nothing else has to. */
          slidesOffsetBefore={edgeOffset}
          slidesOffsetAfter={edgeOffset}
          autoplay={
            autoplay && !reducedMotion
              ? {
                  delay: autoplayDelay,
                  /* Keeps running after a manual nudge, but never while the
                     visitor is reading a card. */
                  disableOnInteraction: false,
                  pauseOnMouseEnter: true,
                }
              : false
          }
          watchOverflow
          a11y={{
            prevSlideMessage: labels.previous,
            nextSlideMessage: labels.next,
          }}
          pagination={{
            el: `#${pagerId}`,
            clickable: true,
            renderBullet: (index, className) =>
              `<button type="button" class="${className}" aria-label="${labels.goToSlide.replace(
                "{n}",
                String(index + 1)
              )}"></button>`,
          }}
          onSwiper={(swiper) => {
            sync(swiper);
            if (looping && !stepped.current) {
              stepped.current = true;
              swiper.slideNext(0);
            }
          }}
          onSlideChange={sync}
          onResize={sync}
          onBreakpoint={sync}
        >
          {properties.map((property, index) => (
            <SwiperSlide key={property.id}>
              <PropertyCard
                template={cardTemplate}
                property={property}
                hrefFor={hrefFor}
                /* Only the first row is above the fold. */
                eager={index < 3}
              />
            </SwiperSlide>
          ))}
        </Swiper>

        <div id={pagerId} className={`${root}__pagination`} />
      </div>
    </section>
  );
}
