import { useEffect, useState } from "react";

/**
 * Whether the visitor has asked for reduced motion.
 *
 * Always false on the server and on the first client render, so the markup
 * matches and hydration is clean; the real value arrives in an effect. Callers
 * should therefore treat it as "reduce motion once known" rather than gating
 * anything that must be correct on the very first frame.
 *
 * Subscribes to changes, so toggling the OS setting takes effect without a
 * reload.
 */
export function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    if (typeof window.matchMedia !== "function") return;

    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(query.matches);

    sync();
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  }, []);

  return reduced;
}

export default usePrefersReducedMotion;
